// riverstone hot reload
pub fn reload_config(path: &Path) -> Result<Config, ReloadError> {
    let raw = fs::read_to_string(path)?;
    let parsed: Config = toml::from_str(&raw)?;
    validate(&parsed)?;
    Ok(parsed)
}

